 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    top = [(0, c, grid[0][c]) for c in range(w) if grid[0][c] != 0]
    for _, c, color in top:
        matches = [(r, x) for r in range(h) for x in range(w)
                   if grid[r][x] == color and r != 0]
        if matches:
            r, x = matches[0]
            # Extend down from top marker, then turn toward the boundary marker.
            for rr in range(1, r + 1):
                out[rr][c] = color
            step = 1 if x > c else -1
            for cc in range(c, x + step, step):
                out[r][cc] = color
        else:
            for rr in range(1, h):
                out[rr][c] = color
    return out
